propuesta.texto_nuevo:
# Si aun asi se pasa del tope, se van soltando BLOQUES ENTEROS desde el final: la cabecera,
# la ley y "a quien puede danar" son LO NECESARIO, no se tocan. Nunca se suelta una linea
# suelta, porque eso corta una funcion a la mitad (evidencia 2026-09-15_101525).
while len("\n".join(salida)) > tope and len(salida) > len(bloques["__cabecera__"]):
    ultima = salida[-1]
    if ultima.startswith("###"):
        # La ultima linea abre un bloque: se busca hacia atras su cabecera (la ultima
        # linea anterior que tambien empiece con el separador de bloque).
        i = len(salida) - 2
        while i >= 0 and not salida[i].startswith("###"):
            i -= 1
        if i < 0:
            # No hay cabecera de bloque: es relleno suelto, se suelta de a una.
            salida.pop()
        elif archivo and archivo in salida[i]:
            # La cabecera del bloque nombra el archivo de la tarea: se conserva el bloque
            # entero aunque pese mas que el tope.
            break
        else:
            # No es el archivo de la tarea: se elimina el bloque entero.
            del salida[i:]
    else:
        # Relleno suelto: se suelta de a una.
        salida.pop()
return "\n".join(salida)

